function format(s, params) {
  if (!params) return s
  return String(s).replace(/\{(\w+)\}/g, (_, k) => (params[k] == null ? '' : String(params[k])))
}

let _t = (key, params) => format(ja[key] || zh[key] || key, params)

export function bindT(fn) { _t = fn }
export function t(key, params) { return _t(key, params) }

export function installLocale(locale) {
  if (!locale?.register) return () => {}
  const disposers = [
    locale.register(NS, 'zh', zh),
    locale.register(NS, 'en', en),
    locale.register(NS, 'ja', ja),
  ]
  if (typeof locale.bind === 'function') bindT(locale.bind(NS))
  return () => { disposers.forEach((d) => { try { d() } catch {} }) }
}
